SSCALC='''<div class="card" style="background:#effcff;margin:14px 0"><h3>🧮 Estimate your 2027 benefit</h3>
<p class="warn" style="margin-top:6px"><b>Estimate only, not personal advice.</b> This multiplies the number you type by 1.036. It runs in your browser and nothing is sent anywhere. SSA rounds amounts and subtracts things like Medicare premiums, so your official COLA notice is the real number.</p>
<form id="colacalc" onsubmit="return false"><label for="cb"><b>Your current monthly benefit before deductions ($)</b></label><br>
<input id="cb" type="number" min="0" max="100000" step="0.01" inputmode="decimal" placeholder="e.g. 1850" style="font:inherit;font-size:1.1rem;padding:6px 10px;border:2px solid #16121f;border-radius:10px;margin:8px 0;width:12em">
<button type="button" id="cgo" style="font:inherit;font-weight:800;border:2px solid #16121f;border-radius:10px;background:#ffd60a;padding:6px 14px;cursor:pointer">Estimate</button>
<p id="cres" aria-live="polite" style="font-weight:800;font-size:1.1rem"></p></form></div>
<script>(function(){var i=document.getElementById("cb"),b=document.getElementById("cgo"),o=document.getElementById("cres");
function f(n){return n.toLocaleString("en-US",{style:"currency",currency:"USD"})}
function go(){var v=parseFloat(i.value);if(!(v>0)){o.textContent="Type your current monthly benefit to see an estimate.";return}var n=Math.round(v*1.036*100)/100;o.textContent="Estimated 2027 benefit: about "+f(n)+" a month, up about "+f(Math.round((n-v)*100)/100)+". Estimate only; check your SSA notice."}
b.addEventListener("click",go);i.addEventListener("keydown",function(e){if(e.key==="Enter"){e.preventDefault();go()}})})();</script>'''
